/* A member's own dated activity journal, separate from management analytics. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),q=s=>document.querySelector(s),key='my-work-report';let generation=0,from='',to='',lastReport=null,reportType='monthly';const dayKey=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d)),today=()=>dayKey(Date.now()),fmt=s=>new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeZone:'Asia/Tehran'}).format(new Date(s.length===10?s+'T12:00:00Z':s)),num=n=>Number(n).toLocaleString('fa-IR'),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));to=today();from=window.SamandisDates?SamandisDates.parse(SamandisDates.display(to).split('/').slice(0,2).join('/')+'/1'):to.slice(0,8)+'01';
const button=document.createElement('button');button.id='myWorkReportNav';button.innerHTML='<span aria-hidden="true">▤</span><span>گزارش کار من</span>';button.onclick=()=>{if(shared&&!mine())return message('ابتدا وارد حساب خود شوید.');if(window.SAMANDIS_PERSONAL_MODE)document.querySelector('[data-team-return]')?.click();if(shared){scope=key;render()}else{view=key;render()}};q('#deskNav').append(button);
const eventNames={report:'گزارش کار / بازخورد',submit:'اعلام انجام کار',approve:'تأیید کار',file:'بارگذاری فایل',created:'تعریف کار',assign:'ارجاع کار',edit:'ویرایش کار',reopen:'بازگشایی کار',correct:'درخواست اصلاح',request:'درخواست همکاری',trash:'حذف کار',restore:'بازیابی کار',import:'ورود اطلاعات'};
async function allRows(factory){let result=[];for(let offset=0;;offset+=500){const rows=await checked(factory().range(offset,offset+499));result.push(...rows);if(rows.length<500)return result}}
function uniqueCompleted(items){
 const normalized=s=>String(s??'').normalize('NFKC').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[\u064b-\u065f\u0670\u0640]/g,'').replace(/[\u200c\u200d]/g,' ').replace(/\s+/g,' ').trim();
 // A reopened/resubmitted task contributes its latest completion day in this report.
 const latest=new Map();for(const item of items){const id=item.taskId||item.day+':'+normalized(item.title),previous=latest.get(id);if(!previous||item.day>=previous.day)latest.set(id,item)}
 const seen=new Set();return [...latest.values()].sort((a,b)=>a.day.localeCompare(b.day)||String(a.title).localeCompare(String(b.title),'fa')).filter(item=>{const title=normalized(item.title),key=item.day+':'+(title&&title!=='کار'?title:item.taskId);if(seen.has(key))return false;seen.add(key);return true});
}
function completedItems(events,memberId,start,end){
 const grouped=new Map();for(const event of events){if(!event.task)continue;const id=event.task_id;if(!grouped.has(id))grouped.set(id,[]);grouped.get(id).push(event)}
 const items=[];for(const [id,history]of grouped){const task=history[0].task;if(!['review','done'].includes(task.status))continue;const mine=task.owner_id===memberId||(task.collaborators||[]).includes(memberId)||history.some(e=>e.kind==='submit'&&e.actor_id===memberId);if(!mine)continue;
 const approvals=history.filter(e=>e.kind==='approve'),submissions=history.filter(e=>e.kind==='submit');const choices=task.status==='done'?[...approvals,...submissions]:submissions;const final=choices.sort((a,b)=>a.created_at.localeCompare(b.created_at)).at(-1);if(!final)continue;const day=dayKey(final.created_at);if(day<start||day>end)continue;items.push({day,taskId:id,title:task.title||final.payload?.before?.title||'کار'})}
 return uniqueCompleted(items);
}
function reportHeading(report){const month=s=>new Intl.DateTimeFormat('fa-IR',{month:'long',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));const year=s=>new Intl.DateTimeFormat('fa-IR',{year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));const sameMonth=month(report.from)===month(report.to)&&year(report.from)===year(report.to);if(report.type==='monthly'&&sameMonth)return 'گزارش ماهیانه '+month(report.from)+'ماه '+year(report.from);return (report.type==='weekly'?'گزارش هفتگی':'گزارش ماهیانه')}
function table(report){const items=uniqueCompleted(report.items),groups=new Map();for(const i of items){if(!groups.has(i.day))groups.set(i.day,[]);groups.get(i.day).push(i)}return '<article class="own-report-paper"><div class="brief-report-header"><div class="brief-company"><img src="'+new URL('samandis.jpg',location.href).href+'" alt="سمندیس"><span>شرکت سمندیس</span></div><div class="brief-heading"><p>'+escape(report.project)+'</p><h1>'+reportHeading(report)+'</h1><h2>'+escape(report.name)+'</h2></div></div><div class="brief-period"><div><span>بازهٔ گزارش</span><b>'+fmt(report.from)+' تا '+fmt(report.to)+'</b></div></div><table class="brief-table"><colgroup><col style="width:24%"><col style="width:76%"></colgroup><thead><tr><th scope="col">روز انجام</th><th scope="col">خلاصهٔ فعالیت‌ها</th></tr></thead><tbody>'+[...groups].map(([day,entries])=>'<tr><td class="brief-date"><b>'+fmt(day)+'</b><small>'+new Intl.DateTimeFormat('fa-IR',{weekday:'long',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'))+'</small></td><td><ul>'+entries.map(i=>'<li>'+escape(i.title)+'</li>').join('')+'</ul></td></tr>').join('')+(items.length?'':'<tr><td colspan="2" class="brief-empty">در این بازه فعالیت تکمیل‌شده‌ای ثبت نشده است.</td></tr>')+'</tbody></table><div class="brief-footer"><span>سمندیس · گزارش عملکرد فردی</span></div></article>'}
const paperCss=window.SAMANDIS_WORK_PAPER_CSS||'';
function htmlReport(){return '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>گزارش کار '+escape(lastReport.name)+'</title><style>'+paperCss+'</style><body class="work-report-export">'+table(lastReport)+'</body></html>'}
function print(){if(!lastReport)return;const frame=document.createElement('iframe');frame.className='own-report-print-frame';frame.title='چاپ گزارش شخصی';frame.onload=()=>{Promise.all([frame.contentDocument.fonts?.ready,...[...frame.contentDocument.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=img.onerror=resolve}))]).then(()=>{frame.contentWindow.focus();frame.contentWindow.print()})};frame.srcdoc=htmlReport();document.querySelector('.own-report-print-frame')?.remove();document.body.append(frame)}
function download(){if(!lastReport)return;const blob=new Blob(['\ufeff'+htmlReport()],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='گزارش-کار-'+lastReport.from+'-'+lastReport.to+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function load(){const token=++generation,host=q(shared?'#sharedContent':'#workspace'),uid=shared?session?.user.id:me(),pid=shared?project?.id:'demo',memberId=shared?mine()?.id:me();if(!host||shared&&!memberId)return;lastReport=null;host.innerHTML='<section class="own-report"><h1>گزارش کار من</h1><p class="shared-meta">خلاصهٔ کارهای تکمیل‌شده یا تأییدشدهٔ شما در بازهٔ انتخابی.</p><div class="own-report-toolbar"><form id="ownReportRange" class="range-controls"><label>نوع گزارش<select name="reportType" id="ownReportType"><option value="monthly" '+(reportType==='monthly'?'selected':'')+'>ماهیانه</option><option value="weekly" '+(reportType==='weekly'?'selected':'')+'>هفتگی</option></select></label><label>از تاریخ<input type="date" name="from" value="'+from+'" required></label><label>تا تاریخ<input type="date" name="to" value="'+to+'" required></label><button class="primary">تهیه گزارش</button></form><div class="own-report-actions"><button id="ownReportPrint" class="primary" disabled>چاپ / ذخیره PDF</button><button id="ownReportDownload" class="secondary" disabled>دریافت گزارش</button></div></div><div id="ownReportBody" aria-live="polite">در حال تهیه گزارش…</div></section>';q('#ownReportRange').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=f.get('from'),b=f.get('to');if(!a||!b||a>b)return(shared?message:toast)('بازهٔ تاریخ معتبر نیست.');reportType=f.get('reportType');from=a;to=b;load()};q('#ownReportType').onchange=e=>{reportType=e.target.value;to=today();if(reportType==='weekly'){const d=new Date(to+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+1)%7);from=d.toISOString().slice(0,10)}else{from=SamandisDates.parse(SamandisDates.display(to).split('/').slice(0,2).join('/')+'/1')}load()};q('#ownReportPrint').onclick=print;q('#ownReportDownload').onclick=download;const a=from,b=to;
try{let items=[];if(shared){const events=await allRows(()=>db.from('sm_events').select('task_id,actor_id,kind,created_at,payload,task:sm_tasks(title,status,owner_id,collaborators)').eq('project_id',pid).in('kind',['submit','approve']).order('created_at').order('id'));items=completedItems(events,memberId,a,b)}else{const events=tasks.flatMap(t=>{const task={title:t.title,owner_id:t.owner,collaborators:t.collaborators||[],status:t.status==='بسته‌شده'?'done':t.status==='آماده بررسی'?'review':'open'};return [...(t.submissions||[]).map(x=>({task_id:t.id,task,kind:'submit',actor_id:x.by,created_at:x.at})),...(t.approvals||[]).map(x=>({task_id:t.id,task,kind:'approve',actor_id:x.by,created_at:x.at}))]});items=completedItems(events,memberId,a,b)}if(token!==generation||(shared?(scope!==key||session?.user.id!==uid||project?.id!==pid):view!==key))return;lastReport={uid,pid,name:shared?mine().name:people[me()],project:shared?project.name:'پروژه دارایی',from:a,to:b,items:uniqueCompleted(items),type:reportType};q('#ownReportBody').innerHTML=table(lastReport);q('#ownReportPrint').disabled=false;q('#ownReportDownload').disabled=false}catch(e){if(token===generation&&q('#ownReportBody'))q('#ownReportBody').textContent=shared?failure(e):e.message}}
const oldRender=render;render=function(...args){const active=(shared?scope:view)===key;if(active&&lastReport&&lastReport.uid===(shared?session?.user.id:me())&&lastReport.pid===(shared?project?.id:'demo')&&q('#ownReportBody'))return;if(!shared&&active){view='mine';try{oldRender(...args)}finally{view=key}}else oldRender(...args);button.classList.toggle('active',active);if(active){document.querySelectorAll('[data-desk-view]').forEach(b=>b.classList.remove('active'));q('#deskCrumb').textContent='گزارش کار من';load()}else{generation++;lastReport=null}};
})();
